const comparisonNotes: Record<Lang, string[]> = {"en": ["A useful support message can be short: the original product page opens, the imported destination shows a different option, and the required color and size are missing. Include the product link and the time you checked it in the private official channel. Ask whether that specific option can be purchased before asking about payment. This keeps the question focused and avoids submitting an order that support must later untangle.", "For a repeatable comparison, label the cases A and B and keep a separate column for assumptions. Case A can retain the original boxes; case B can use a different packaging arrangement only if that arrangement is actually offered and suitable for the contents. Obtain a separate packed result for each feasible case. Do not reuse the smaller case’s dimensions with the larger case’s physical weight simply to produce a lower estimate. If a packaging change affects protection, record that trade-off alongside the price rather than treating the lowest total as the only decision criterion."], "de": ["Eine kurze Supportfrage reicht oft: Die Quelle öffnet, der Import zeigt eine andere Option und die benötigte Farbe oder Größe fehlt. Sende Link und Prüfzeit im privaten offiziellen Kanal. Frage zuerst, ob genau diese Variante gekauft werden kann, bevor du die Zahlung klärst. So entsteht kein Auftrag, der später korrigiert werden muss.", "Beschrifte Vergleichsfälle mit A und B und führe Annahmen separat. A kann Originalkartons behalten; B darf eine andere Verpackung nur verwenden, wenn sie angeboten wird und passt. Nutze je möglichem Fall eigene Packdaten. Kombiniere nicht die Maße des kleinen Falls mit dem Gewicht des großen, um einen niedrigeren Preis zu erzeugen. Halte eine mögliche Änderung des Schutzes neben der Ersparnis fest."], "es": ["Una consulta breve basta: la fuente abre, la importación muestra otra opción y faltan el color o la talla necesarios. Envía enlace y hora de comprobación por el canal oficial privado. Pregunta si esa variante concreta puede comprarse antes de hablar del pago. Así evitas un pedido que después deba corregirse.", "Etiqueta los casos A y B y separa las suposiciones. A puede conservar cajas originales; B puede usar otra disposición solo si se ofrece y protege el contenido. Obtén datos embalados propios para cada caso viable. No combines dimensiones del caso menor con el peso del mayor para forzar una estimación baja. Registra cualquier cambio de protección junto al precio: el menor total no es el único criterio."], "fr": ["Une demande courte suffit : la source s’ouvre, l’importation affiche une autre option et la couleur ou taille voulue manque. Transmettez lien et heure du contrôle par le canal officiel privé. Demandez d’abord si cette variante précise peut être achetée, avant le paiement. Cela évite une commande qu’il faudrait ensuite corriger.", "Nommez les cas A et B et séparez les hypothèses. A peut garder les boîtes d’origine ; B peut utiliser une autre disposition seulement si elle est proposée et adaptée. Obtenez des données emballées propres à chaque cas réalisable. Ne mélangez pas les petites dimensions d’un cas avec le poids de l’autre pour forcer un prix inférieur. Notez l’effet sur la protection à côté de l’économie : le total minimal n’est pas le seul critère."], "it": ["Una richiesta breve può bastare: la fonte si apre, l’importazione mostra un’altra opzione e mancano colore o taglia desiderati. Invia link e ora del controllo nel canale ufficiale privato. Chiedi prima se quella variante sia acquistabile, poi del pagamento. Eviti così un ordine da correggere successivamente.", "Etichetta i casi A e B e separa le ipotesi. A può mantenere le scatole originali; B può usare un altro imballaggio solo se offerto e adatto al contenuto. Ottieni dati del pacco specifici per ogni caso possibile. Non unire le misure del caso piccolo con il peso dell’altro per abbassare artificialmente la stima. Registra l’effetto sulla protezione accanto al prezzo: il totale minimo non è l’unico criterio."]};

export function priorityArticles(lang: Lang): ResearchArticle[] {
  return [linkGuideSlug, usGuideSlug].map((slug) => ({
    slug, ...content[lang][slug],
    sections: content[lang][slug].sections.map((section, index) => index === 5 ? { ...section, p: [...section.p, comparisonNotes[lang][slug === linkGuideSlug ? 0 : 1]] } : section),
    published: "2026-10-15", modified: "2026-10-15",
    readingTime: "8 min", sourceBasis: basis[lang],
  }));
}
